/*
 * A374664  Nonnegative numbers whose binary expansion has no ones in common
 *          with some of its cyclic shifts.
 * https://oeis.org/A374664
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   not stated
 * Range:     u8 n <= 60, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   bitlen_seq_t, grow_seq_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Compute a(n): the nth term of OEIS A374664.
 * The sequence is generated by a brute‑force search.  A number k≥0
 * is selected if its binary expansion has at least one cyclic shift
 * that is disjoint from itself (i.e. (k & rot(k,s)) == 0 for some
 * shift s with 1 ≤ s < bitlen(k)).  The first terms are
 * 0,2,4,8,9,10,12,… */
#include <stddef.h>
#include <stdbool.h>
#include "../utils/bitlen_seq_t.h"
#include "../utils/grow_seq_array.h"

static seq_t *cache = NULL;           /* cached sequence values   */
static size_t cache_len = 0;          /* number of cached values  */
static size_t cache_cap = 0;          /* buffer capacity          */
static seq_t next_to_test = 0;        /* next number to examine   */

/* Return true if k satisfies the definition of A374664. */
static bool is_good(seq_t k) {
    if (k == (seq_t)0) return true;          /* 0 always works */

    unsigned L = bitlen_seq_t(k);           /* bit length of k */
    for (unsigned s = 1; s < L; ++s) {
        seq_t mask  = (((seq_t)1 << s) - (seq_t)1);      /* lower s bits */
        seq_t low   = k & mask;
        seq_t high  = k >> s;
        seq_t rot   = (low << (L - s)) | high;          /* cyclic shift */

        if ((k & rot) == (seq_t)0) return true;        /* disjoint shift found */
    }
    return false;
}

/* Return the nth term of the sequence (a(1)=0). */
seq_t a(idx_t n) {
    if (n == 0) return 0; /* safety – n is always ≥1 in the problem */

    while (cache_len < n) {
        if (is_good(next_to_test)) {
            /* ensure enough space in the cache */
            if (cache_len >= cache_cap) {
                size_t new_cap = cache_cap ? cache_cap * 2 : 8;
                grow_seq_array(&cache, &cache_cap, new_cap);
            }
            cache[cache_len++] = next_to_test;
        }
        next_to_test++;
    }
    return cache[n-1];
}
